import csv

# Check for RFC 4180 compliance - each row should have exactly 7 fields
with open('outputs/t02_eurostat_raw.csv', 'r', newline='') as f:
    reader = csv.reader(f)
    header = next(reader)

    issues = []
    row_num = 0
    for row in reader:
        row_num += 1
        if len(row) != 7:
            issues.append(f'Row {row_num}: has {len(row)} fields instead of 7')
        if row_num <= 3:
            print(f'Row {row_num}: {row}')

    if issues:
        print('Issues found:')
        for issue in issues[:5]:
            print(issue)
    else:
        print('All rows have exactly 7 fields - RFC 4180 compliant!')
"
"}

{"command":"python3 -c "
import csv

# Check for any fields that need quoting (contain comma, quote, or newline)
with open('outputs/t02_eurostat_raw.csv', 'r', newline='') as f:
    reader = csv.reader(f)
    header = next(reader)

    issues = []
    row_num = 0
    for row in reader:
        row_num += 1
        # Check if any field contains comma, quote, or newline
        for i, field in enumerate(row):
            if ',' in field or '\"' in field or '\n' in field:
                issues.append(f'Row {row_num}, field {i}: {repr(field)}')

        if row_num <= 2:
            print(f'Row {row_num}: {row}')

    if issues:
        print('Issues found:')
        for issue in issues[:5]:
            print(issue)
    else:
        print('No RFC 4180 issues found - all fields properly quoted when needed!')
"
"}

